/** Residents' day (see src/economy/residents.ts). Returns what they ate per `merchant:good`, so tourists buy less. */
async function residentTurn(cfg, provider, relayer, secret, day, log, txs, agentCfg, agentStore, mint = true) {
	const ate = {};
	for (const r of RESIDENTS) {
		const accountId = `${r.id}.${cfg.relayerId}`;
		if (!await view(provider, cfg.contractId, "is_registered", { account_id: accountId }).catch(() => false)) continue;
		if (!await claimOnce(cfg, `resident:${r.id}:${day}`, Math.ceil(600) * 2)) continue;
		const me = new Account(accountId, provider, new KeyPairSigner(residentKey(r.id, secret)));
		const call = async (who, method, args) => {
			const res = outcome(await who.signAndSendTransaction({
				receiverId: cfg.contractId,
				actions: [actions.functionCall(method, args, TICK_GAS, 0n)],
				throwOnFailure: false
			}));
			txs.push(res.txHash);
			return res;
		};
		if (mint) {
			const work = await call(relayer, "operator_mint", {
				account_id: accountId,
				token_id: r.good,
				amount: String(r.perDay),
				reason: r.reason
			});
			if (!work.ok) {
				log.push(`${r.id} work FAILED: ${work.error}`);
				continue;
			}
		}
		const held = Object.fromEntries((await view(provider, cfg.contractId, "get_balances", { account_id: accountId })).map(([t, v]) => [t, Number(v)]));
		const stalls = (await chainEconomy(provider, cfg)).merchants;
		const dec = await decideResident({
			store: agentStore,
			cfg: agentCfg,
			res: r,
			offers: executableOffers(await view(provider, cfg.contractId, "get_offers", {}), stalls),
			coin: held.coin ?? 0,
			holding: held[r.good] ?? 0,
			day,
			fetchImpl: fetch
		});
		if (dec.skip) {
			log.push(`resident ${r.id} decision is held by another tick`);
			continue;
		}
		const plan = dec.plan;
		if (dec.decision) log.push(`resident ${r.id} ${dec.decision.source === "ai" ? "NEAR AI" : "rule"} plan: ${dec.decision.action}${dec.decision.fallbackReason ? ` (${dec.decision.fallbackReason})` : ""}`);
		let carried = null;
		if (plan.sell) {
			const s = await call(me, "sell", {
				buyer: plan.sell.buyer,
				token_id: r.good,
				qty: String(plan.sell.qty),
				min_price: String(plan.sell.price)
			});
			log.push(`resident ${r.id} sold ${plan.sell.qty} ${r.good} to ${plan.sell.merchant} at ${plan.sell.price} c${s.ok ? "" : ` FAILED: ${s.error}`}`);
			if (!s.ok) continue;
			carried = s.txHash;
		}
		if (plan.eat) {
			const b = await call(me, "buy", {
				seller: plan.eat.seller,
				token_id: r.food,
				qty: "1",
				max_price: String(plan.eat.price)
			});
			if (b.ok) {
				carried ??= b.txHash;
				const e = await call(relayer, "operator_burn", {
					account_id: accountId,
					token_id: r.food,
					amount: "1",
					reason: "eaten"
				});
				ate[`${plan.eat.merchant}:${r.food}`] = (ate[`${plan.eat.merchant}:${r.food}`] ?? 0) + 1;
				log.push(`resident ${r.id} bought 1 ${r.food} from ${plan.eat.merchant} at ${plan.eat.price} c and ate it${e.ok ? "" : ` (eat FAILED: ${e.error})`}`);
			} else log.push(`resident ${r.id} buy ${r.food} FAILED: ${b.error}`);
		} else if (plan.hungry !== null) log.push(`resident ${r.id} could not afford ${r.food} at ${plan.hungry} c`);
		if (dec.decision && carried) await attachTx(agentStore, r.id, day, carried).catch(() => void 0);
	}
	return ate;
}
async function tick(cfg, env) {
	if (!await claimTick(cfg)) return json(200, {
		status: "skipped",
		message: "the merchants moved less than a minute ago"
	});
	const secret = (env.NEAR_MERCHANT_SECRET ?? "").trim();
	if (!secret) throw new HttpError(503, "merchant keys not configured");
	const { provider, relayer } = account(cfg);
	const st = await chainEconomy(provider, cfg);
	const posted = new Map((await view(provider, cfg.contractId, "get_offers", {})).map((o) => [orderKey(o), o]));
	const agentCfg = agentConfig(env);
	const agentStore = decisionStore(cfg);
	const signerOf = (id) => new Account(`${id}.${cfg.relayerId}`, provider, new KeyPairSigner(merchantKey(id, secret)));
	const log = [];
	const txs = [];
	const day = Math.floor(Date.now() / MARKET_DAY_MS);
	if (MERCHANTS.some((id) => Number(st.flags[`lastSettled.${id}`]) < day - 1) && await hit(cfg, `settled:${day - 1}`, 1, Math.ceil(600) * 2)) {
		const r = outcome(await relayer.signAndSendTransaction({
			receiverId: cfg.contractId,
			actions: MERCHANTS.map((merchant) => actions.functionCall("settle_day", {
				day: day - 1,
				merchant
			}, teraToGas("60"), 0n)),
			throwOnFailure: false
		}));
		txs.push(r.txHash);
		log.push(`dividends for market day ${day - 1} settled${r.ok ? "" : ` FAILED: ${r.error}`}`);
	}
	const rentCalls = [];
	for (const id of MERCHANTS) {
		const m = st.merchants[id];
		if (m.status !== "open" || day % m.rentEveryDays !== 0 || Number(st.flags[`lastRent.${id}`]) >= day) continue;
		if (!await hit(cfg, `rent:${id}:${day}`, 1, Math.ceil(600) * 2)) continue;
		const need = closingNeed(st, id);
		rentCalls.push(actions.functionCall("charge_rent", {
			day,
			merchant: id,
			rent: String(m.rent),
			reopen_need: String(need)
		}, TICK_GAS, 0n));
		if (m.cash >= m.rent) {
			m.cash -= m.rent;
			log.push(`${id} paid ${m.rent} c rent`);
		} else {
			m.status = "closed";
			st.flags[`reopenNeed.${id}`] = Math.max(1, need);
			log.push(`${id} could not pay ${m.rent} c rent and closed (reopens after ${Math.max(1, need)} mangoes)`);
		}
	}
	if (rentCalls.length) {
		const r = outcome(await relayer.signAndSendTransaction({
			receiverId: cfg.contractId,
			actions: rentCalls,
			throwOnFailure: false
		}));
		txs.push(r.txHash);
		if (!r.ok) {
			log.push(`rent FAILED: ${r.error}`);
			st.merchants = (await chainEconomy(provider, cfg)).merchants;
		}
	}
	const guildCalls = await guildTurn(cfg, provider, st, day, log);
	if (guildCalls.length) {
		const r = outcome(await relayer.signAndSendTransaction({
			receiverId: cfg.contractId,
			actions: guildCalls,
			throwOnFailure: false
		}));
		txs.push(r.txHash);
		if (!r.ok) {
			log.push(`guild FAILED: ${r.error}`);
			st.merchants = (await chainEconomy(provider, cfg)).merchants;
		}
	}
	const repriced = await Promise.all(MERCHANTS.map(async (id) => {
		const m = st.merchants[id];
		const calls = [];
		const want = (side, token, qty, price) => {
			const cur = posted.get(`${id}|${side}|${token}`);
			if (qty <= 0) {
				if (cur) calls.push(actions.functionCall(side === "ask" ? "list" : "bid", {
					token_id: token,
					qty: "0",
					price: "1"
				}, TICK_GAS, 0n));
				return;
			}
			if (cur && Number(cur.qty) === qty && Number(cur.price) === price) return;
			calls.push(actions.functionCall(side === "ask" ? "list" : "bid", {
				token_id: token,
				qty: String(qty),
				price: String(price)
			}, TICK_GAS, 0n));
		};
		const lever = LEVERS[id];
		let agent = null, skipLever = false, leverPrice = null;
		if (lever && agentCfg.enabled.has(id)) {
			const out = await decideBid({
				store: agentStore,
				cfg: agentCfg,
				st,
				id,
				offers: [...posted.values()],
				day,
				fetchImpl: fetch
			});
			agent = out.decision;
			skipLever = out.skipBid;
			if (agent) leverPrice = out.price;
			if (agent) log.push(`${id} ${agent.source === "ai" ? "NEAR AI" : "rule"} decision: ${agent.action} ${lever.good} ${lever.side} ${agent.basePrice} -> ${agent.price} c${agent.fallbackReason ? ` (${agent.fallbackReason})` : ""}`);
		}
		const isLever = (side, good) => lever !== void 0 && lever.side === side && lever.good === good;
		for (const good of m.sells) {
			if (skipLever && isLever("ask", good)) continue;
			want("ask", good, m.status === "open" ? m.stock[good] : 0, isLever("ask", good) && leverPrice !== null ? leverPrice : quote(st, id, good, false).price);
		}
		for (const good of ["mango", "lemon"]) {
			const b = bidFor(st, id, good);
			const price = isLever("bid", good) && leverPrice !== null ? leverPrice : b?.price ?? 1;
			if (skipLever && isLever("bid", good)) continue;
			want("bid", good, b ? Math.min(b.qty, Math.floor(m.cash / Math.max(1, price))) : 0, price);
		}
		const hashes = [];
		for (const call of calls) {
			const isAgentCall = (c) => agent !== null && lever !== void 0 && c.functionCall?.methodName === (lever.side === "ask" ? "list" : "bid") && JSON.parse(new TextDecoder().decode(c.functionCall.args)).token_id === lever.good;
			const agentBid = isAgentCall(call);
			if (agentBid && !await claimBidSend(agentStore, id, day).catch(() => true)) {
				hashes.push("");
				log.push(`${id} ${lever.good} ${lever.side} already sent for market day ${day}`);
				continue;
			}
			const r = outcome(await signerOf(id).signAndSendTransaction({
				receiverId: cfg.contractId,
				actions: [call],
				throwOnFailure: false
			}));
			if (agentBid && !r.ok) await releaseBidSend(agentStore, id, day).catch(() => void 0);
			hashes.push(r.txHash);
			const fc = call.functionCall;
			const a = JSON.parse(new TextDecoder().decode(fc.args));
			log.push(`${id} ${fc.methodName === "list" ? "asks" : "bids"} ${a.qty === "0" ? "withdrawn for" : `${a.qty} x ${a.price} c${a.per ? ` per ${a.per}` : ""} for`} ${a.token_id}${r.ok ? "" : ` FAILED: ${r.error}`}`);
		}
		if (agent) {
			const at = calls.findIndex((c) => lever !== void 0 && c.functionCall?.methodName === (lever.side === "ask" ? "list" : "bid") && JSON.parse(new TextDecoder().decode(c.functionCall.args)).token_id === lever.good);
			if (at >= 0 && hashes[at]) await attachTx(agentStore, id, day, hashes[at]).catch(() => void 0);
		}
		return hashes;
	}));
	txs.push(...repriced.flat());
	for (const t of planMerchantTrades(st)) {
		const r = outcome(await signerOf(t.buyer).signAndSendTransaction({
			receiverId: cfg.contractId,
			actions: [actions.functionCall("buy", {
				seller: `${t.seller}.${cfg.relayerId}`,
				token_id: t.good,
				qty: String(t.qty),
				max_price: String(t.price)
			}, TICK_GAS, 0n)],
			throwOnFailure: false
		}));
		txs.push(r.txHash);
		log.push(`${t.buyer} bought ${t.qty} ${t.good} from ${t.seller} at ${t.price} c (${t.reason})${r.ok ? "" : ` FAILED: ${r.error}`}`);
	}
	const ate = await residentTurn(cfg, provider, relayer, secret, day, log, txs, agentCfg, agentStore);
	const op = [];
	for (const id of MERCHANTS) {
		const m = st.merchants[id];
		if (m.status !== "open") continue;
		for (const good of m.sells) {
			const units = Math.max(0, Math.min(m.stock[good], Math.floor(shopperWant(st, id, good) * TICK_HOURS)) - (ate[`${id}:${good}`] ?? 0));
			if (units > 0) op.push(actions.functionCall("street_sale", {
				merchant: id,
				token_id: good,
				qty: String(units),
				unit_price: String(quote(st, id, good, false).price)
			}, TICK_GAS, 0n));
			if (units > 0) log.push(`tourists bought ${units} ${good} from ${id}`);
		}
	}
	const tomas = st.merchants.tomas;
	const nearlyOut = tomas.stock.mango < 6;
	const harborQty = tomas.status === "open" && (nearlyOut || tomas.stock.mango < tomas.target.mango) && (nearlyOut || await hit(cfg, `harbor:${day}`, 1, Math.ceil(600))) ? Math.min(Math.round(tomas.target.mango * 1.4) - tomas.stock.mango, Math.floor(tomas.cash / HARBOR_COST)) : 0;
	if (harborQty > 0) {
		op.push(actions.functionCall("operator_burn", {
			account_id: `tomas.${cfg.relayerId}`,
			token_id: "coin",
			amount: String(harborQty * HARBOR_COST),
			reason: "harbor freight"
		}, TICK_GAS, 0n));
		op.push(actions.functionCall("operator_mint", {
			account_id: `tomas.${cfg.relayerId}`,
			token_id: "mango",
			amount: String(harborQty),
			reason: "harbor standing contract"
		}, TICK_GAS, 0n));
		log.push(`harbor delivered ${harborQty} mangoes to tomas for ${harborQty * HARBOR_COST} c`);
	}
	const arin = st.merchants.arin;
	const batches = Math.min(arin.stock.mango, Math.max(0, Math.ceil((8 - arin.stock.lassi) / 4)));
	if (batches > 0) {
		op.push(actions.functionCall("operator_burn", {
			account_id: `arin.${cfg.relayerId}`,
			token_id: "mango",
			amount: String(batches),
			reason: "tea kitchen"
		}, TICK_GAS, 0n));
		op.push(actions.functionCall("operator_mint", {
			account_id: `arin.${cfg.relayerId}`,
			token_id: "lassi",
			amount: String(batches * 4),
			reason: "tea kitchen"
		}, TICK_GAS, 0n));
		log.push(`arin's kitchen made ${batches * 4} lassi from ${batches} mangoes`);
	}
	if (op.length) {
		const r = outcome(await relayer.signAndSendTransaction({
			receiverId: cfg.contractId,
			actions: op,
			throwOnFailure: false
		}));
		txs.push(r.txHash);
		if (!r.ok) log.push(`operator FAILED: ${r.error}`);
	}
	const last = {
		at: Date.now(),
		day,
		txs: txs.length,
		failed: log.filter((l) => /FAILED/.test(l)).length
	};
	await kv(cfg, [
		"SET",
		LAST_TICK,
		JSON.stringify(last)
	]).catch(() => null);
	return json(200, {
		status: "onchain",
		txHashes: txs,
		log
	});
}
/** The Mango Orchard: ORCHARD_PICK mangoes to a registered player, once per account per market day (atomic day
*  key), minted as goods with the reason "orchard picking". Also capped per IP so new guests can't farm it. */
async function pick(cfg, req) {
	const b = await readJson(req);
	const player = String(b.account ?? "");
	if (!/^[a-z0-9._-]{2,64}$/.test(player) || !player.endsWith(`.${cfg.relayerId}`)) throw new HttpError(400, "bad account id");
	if (!await hit(cfg, `pick:${clientIp(req)}`, LIMITS.pick.max, LIMITS.pick.windowSec)) throw new HttpError(429, "slow down");
	const { provider, relayer } = account(cfg);
	if (!await view(provider, cfg.contractId, "is_registered", { account_id: player })) throw new HttpError(400, "unregistered account");
	const key = `pick:${player}:${Math.floor(Date.now() / MARKET_DAY_MS)}`;
	if (!await claimOnce(cfg, key, Math.ceil(600) * 2)) return json(200, {
		status: "picked",
		message: "already picked this market day"
	});
	const r = outcome(await relayer.signAndSendTransaction({
		receiverId: cfg.contractId,
		actions: [actions.functionCall("operator_mint", {
			account_id: player,
			token_id: "mango",
			amount: String(3),
			reason: "orchard picking"
		}, TICK_GAS, 0n)],
		throwOnFailure: false
	}));
	if (!r.ok) await releaseOnce(cfg, key);
	return json(r.ok ? 200 : 502, {
		status: r.ok ? "onchain" : "failed",
		qty: 3,
		txHash: r.txHash,
		message: r.error
	});
}
/** "Ask why": a merchant explains its price and its day from facts read on NEAR (see talk.ts). Read-only on chain;
*  NEAR AI phrases it when NEAR_AI_KEY and NEAR_AI_MODEL are set (server-side only), else the scripted line. */
async function talk(cfg, req, env) {
	const b = await readJson(req);
	const id = String(b.npc ?? "");
	if (!MERCHANTS.includes(id)) throw new HttpError(400, "unknown merchant");
	if (!await hit(cfg, `talk:${clientIp(req)}`, LIMITS.talk.max, LIMITS.talk.windowSec)) throw new HttpError(429, "slow down");
	const { provider } = account(cfg);
	const [st, offers, receipts] = await Promise.all([
		chainEconomy(provider, cfg),
		view(provider, cfg.contractId, "get_offers", {}),
		view(provider, cfg.contractId, "get_receipts", { account_id: `${id}.${cfg.relayerId}` }).catch(() => [])
	]);
	const { facts, script } = factsFor(st, id, offers, receipts);
	const ai = {
		key: (env.NEAR_AI_KEY ?? "").trim() || null,
		model: (env.NEAR_AI_MODEL ?? "").trim() || null
	};
	return json(200, await answer(ai, id, facts, script, typeof b.question === "string" ? b.question : ""));
}
/** Pays a player the whole coins of dividends they are owed (the contract can only ever pay what is owed). Players'
*  own trades claim too; this lets dividends land for someone who is only watching. */
async function claim(cfg, req) {
	const b = await readJson(req);
	const player = String(b.account ?? "");
	if (!/^[a-z0-9._-]{2,64}$/.test(player)) throw new HttpError(400, "bad account id");
	if (!await hit(cfg, `claim:${player}`, LIMITS.claim.max, LIMITS.claim.windowSec)) throw new HttpError(429, "slow down");
	const { provider, relayer } = account(cfg);
	const coins = (await view(provider, cfg.contractId, "get_pending", { account_id: player })).reduce((n, p) => n + Number(p.coins), 0);
	if (coins === 0) return json(200, {
		status: "nothing",
		coins: 0
	});
	const r = outcome(await relayer.signAndSendTransaction({
		receiverId: cfg.contractId,
		actions: [actions.functionCall("claim", { account_id: player }, TICK_GAS, 0n)],
		throwOnFailure: false
	}));
	return json(r.ok ? 200 : 502, {
		status: r.ok ? "onchain" : "failed",
		coins,
		txHash: r.txHash,
		message: r.error
	});
}
async function settle(cfg) {
	if (!await hit(cfg, "settle", LIMITS.settle.max, LIMITS.settle.windowSec)) throw new HttpError(429, "slow down");
	const day = Math.floor(Date.now() / MARKET_DAY_MS);
	const { relayer } = account(cfg);
	const r = outcome(await relayer.signAndSendTransaction({
		receiverId: cfg.contractId,
		actions: MERCHANTS.map((merchant) => actions.functionCall("settle_day", {
			day,
			merchant
		}, teraToGas("60"), 0n)),
		throwOnFailure: false
	}));
	return json(r.ok ? 200 : 502, {
		status: r.ok ? "onchain" : "failed",
		day,
		txHash: r.txHash,
		message: r.error
	});
}
/** Entry point for both runtimes. `route` is the last path segment under /api/near/. */
async function handle(route, req, env) {
	const cfg = readConfig(env);
	try {
		if (route === "status" && req.method === "GET") return await status(cfg);
		if (req.method !== "POST") return json(405, {
			status: "error",
			message: "method not allowed"
		});
		if (route === "voice") {
			const origin = req.headers.get("origin");
			if (origin && new URL(origin).host !== new URL(req.url).host) return json(403, {
				status: "error",
				message: "cross-origin requests not allowed"
			});
			if (!await hit(cfg, `voice:${clientIp(req)}`, LIMITS.voice.max, LIMITS.voice.windowSec)) return json(429, {
				status: "error",
				message: "slow down"
			});
			const b = await readJson(req);
			const r = await synthesize(String(b.speaker ?? ""), String(b.text ?? ""), env.ELEVENLABS_API_KEY?.trim());
			return json(r.status, r.body);
		}
		if (!configured(cfg)) return json(503, {
			status: "unconfigured",
			message: "NEAR relayer not configured (see docs/DEPLOY.md)"
		});
		const origin = req.headers.get("origin");
		if (origin && new URL(origin).host !== new URL(req.url).host) return json(403, {
			status: "error",
			message: "cross-origin requests not allowed"
		});
		if (route === "guest") return await guest(cfg, req);
		if (route === "relay") return await relay(cfg, req);
		if (route === "settle") return await settle(cfg);
		if (route === "deal") return await deal(cfg, req, env);
		if (route === "tick") return await tick(cfg, env);
		if (route === "decisions" && req.method === "GET") {
			const who = new URL(req.url).searchParams.get("merchant") ?? "";
			if (![...MERCHANTS, ...RESIDENTS.map((r) => r.id)].includes(who)) return json(200, { decisions: [] });
			const store = decisionStore(cfg), day = Math.floor(Date.now() / MARKET_DAY_MS);
			const ds = await recentDecisions(store, who, day).catch(() => []);
			const live = await (async () => {
				try {
					return await livePrices(store, await view(account(cfg).provider, cfg.contractId, "get_offers", {}), day);
				} catch {
					return [];
				}
			})();
			return json(200, { decisions: ds.map((d) => ({
				...d,
				live: live.some((p) => p.id === d.merchant && d.day === day)
			})) });
		}
		if (route === "pick") return await pick(cfg, req);
		if (route === "talk") return await talk(cfg, req, env);
		if (route === "social") return await social(cfg, req, env);
		if (route === "claim") return await claim(cfg, req);
		if (route === "register") return await register(cfg, req);
		if (route === "save") return await cloudSave(cfg, req);
		if (route === "load") return await cloudLoad(cfg, req);
		return json(404, {
			status: "error",
			message: "unknown route"
		});
	} catch (e) {
		if (e instanceof HttpError) return json(e.status, {
			status: "error",
			message: e.message
		});
		const message = e instanceof Error ? e.message.split("\n")[0].replace(/ed25519:[1-9A-HJ-NP-Za-km-z]{40,}/g, "[key]").slice(0, 160) : "error";
		return json(502, {
			status: "failed",
			message
		});
	}
}
// server/near/vercel.ts
const route = (req) => new URL(req.url).pathname.split("/").filter(Boolean).pop() ?? "";
async function GET(req) {
	return handle(route(req), req, process.env);
}
async function POST(req) {
	return handle(route(req), req, process.env);
}
